import{_ as a,o as e,c as r,a4 as o}from"./chunks/framework.B0hSrcZ6.js";const n="/info/01-what-is.webp",s="/info/01-what-is-s1.webp",i="/info/01-what-is-s2.webp",l="/info/01-what-is-s3.webp",d="/info/01-what-is-s6.webp",m=JSON.parse('{"title":"第 1 章 Grok Bot 是什么：一个自带电脑的 AI 同事","description":"全面解析雇 Grok Bot 作为 AI 员工的底层机制与云电脑隔离接管边界，对比 Muse 与 Hermes 等常驻 Agent 的选型差异，结合情报调研与电商运营等真实岗位案例，指导新手编写规范岗位说明并设立人工审批闸门。","frontmatter":{},"headers":[],"relativePath":"part1/01-what-is.md","filePath":"part1/01-what-is.md","lastUpdated":1792419518000}'),h={name:"part1/01-what-is.md"};function p(c,t,g,u,k,b){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="第-1-章-grok-bot-是什么-一个自带电脑的-ai-同事" tabindex="-1">第 1 章 Grok Bot 是什么：一个自带电脑的 AI 同事 <a class="header-anchor" href="#第-1-章-grok-bot-是什么-一个自带电脑的-ai-同事" aria-label="Permalink to &quot;第 1 章 Grok Bot 是什么：一个自带电脑的 AI 同事&quot;">​</a></h1><p>传统网页对话无法积累资产，<strong>合上电脑任务直接中断</strong>。面对跨软件调用与持续巡检，人依然被拴在电脑前机械点击。</p><p>本章包含四项核心内容。</p><ul><li>它的运行机制与共享云电脑的物理边界；</li><li>适合与不适合承接的任务类型；</li><li>它与市面上其他常驻 Agent 的选型差异；</li><li><strong>写出符合规范的岗位说明，并设立防止越权的人工审批闸门</strong>。</li></ul><p><img src="'+n+'" alt="Grok Bot 是什么：一个自带电脑的 AI 同事" width="1600" height="1013" decoding="async"></p><h2 id="产品机制-环境底座与思考模型拆分" tabindex="-1">Grok Bot 的底层运行机制是什么？ <a class="header-anchor" href="#产品机制-环境底座与思考模型拆分" aria-label="Permalink to &quot;Grok Bot 的底层运行机制是什么？ {#产品机制-环境底座与思考模型拆分}&quot;">​</a></h2><p><strong>Grok Bot 核心是将常驻云端的 Linux 底座与按需调度的思考模型拆分，配有终端、浏览器和持久文件，即便电脑关机合盖，后台任务照样能在云电脑中继续运行。</strong></p><p><img src="'+s+'" alt="产品机制：环境底座与思考模型拆分" width="1600" height="1013" loading="lazy" decoding="async"></p><p>xAI 与 Cursor 在 2026 年 8 月 11 日推出 Grok Bot，<strong>核心是把环境底座与思考模型拆分</strong>。</p><ul><li><strong>底座（Harness）</strong>：常驻云端，配有 Linux 终端、浏览器和持久文件。关机合盖，后台任务照常跑。</li><li><strong>模型（Brain）</strong>：按需调度。2026 年 10 月 7 日默认切为 Claude Opus 5.5，可派生 Cursor Agent 协同编码。</li></ul><table tabindex="0"><thead><tr><th>工具</th><th>运行环境</th><th>离线与协作</th></tr></thead><tbody><tr><td>聊天助手</td><td>临时网页</td><td>关网页即断，单次对话</td></tr><tr><td>命令行 Agent</td><td>本地终端</td><td>退出即停，限本地仓库</td></tr><tr><td>Grok Bot</td><td>持久云电脑</td><td><strong>关机仍运行</strong>，跨任务文件交接</td></tr></tbody></table><p>机制参考 <a href="https://jcng5q8n0f3z.feishu.cn/wiki/I04Gw3wEaisftUkBikxcg43rnpc" target="_blank" rel="noreferrer">《1.1 Grok Bot 是什么：一页看懂》</a>。</p><h2 id="共享云电脑的物理边界与接管机制" tabindex="-1">Grok Bot 共享云电脑如何隔离与接管？ <a class="header-anchor" href="#共享云电脑的物理边界与接管机制" aria-label="Permalink to &quot;Grok Bot 共享云电脑如何隔离与接管？ {#共享云电脑的物理边界与接管机制}&quot;">​</a></h2><p><strong>同账号所有 Bot 共用云电脑且无法隔离路径与 Cookie，跨任务交接需在 /workspace 存文件，遇输密码或付款等操作可点击 Take over 手动接管。</strong></p><p><img src="'+i+'" alt="共享云电脑的物理边界与接管机制" width="1600" height="1013" loading="lazy" decoding="async"></p><p>同账号所有 Bot 共用云电脑。Heavy 档实测至强 8 核 8 线程、16GB 内存、128GB 硬盘（未核，官方为准），v0.68.1 分辨率升到 1920×1200。</p><p>规范见 <a href="https://cursor.com/cn/docs/grok-bot/work#the-computer-and-apps" target="_blank" rel="noreferrer">Grok Bot 计算机和应用文档</a>。</p><ul><li>新建 Bot <strong>无法隔离权限</strong>。共用路径和登录态，都能读 Cookie。</li><li>跨 Bot 协同依赖文件落盘。私聊天然隔离，交接要在 <code>/workspace</code> 存文件。</li><li>输密码、两步验证或付款点 Take over 处理，<strong>切勿在聊天框发明文密码</strong>。</li><li>控制本地须单独授权。与本地隔离，去 Settings → General → Agent → Execution on Local Computer 开启，执行时弹窗确认。</li></ul><h2 id="适合与不适合的任务类型" tabindex="-1">Grok Bot 适合与不适合做哪些任务？ <a class="header-anchor" href="#适合与不适合的任务类型" aria-label="Permalink to &quot;Grok Bot 适合与不适合做哪些任务？ {#适合与不适合的任务类型}&quot;">​</a></h2><p><strong>Grok Bot 适合流程固定、高频重复且需跨工具调用的任务，例如情报巡检与缺陷复现，但不适合即时问答、本地写码及无人工闸门的高危操作。</strong></p><p><img src="'+l+'" alt="适合与不适合的任务类型" width="1600" height="1013" loading="lazy" decoding="async"></p><h3 id="任务过滤标准" tabindex="-1">任务过滤标准 <a class="header-anchor" href="#任务过滤标准" aria-label="Permalink to &quot;任务过滤标准&quot;">​</a></h3><p><strong>任务该不该交给 Grok Bot，直接看三条过滤标准。</strong></p><ul><li>能在网页端、终端或通过 API 完整跑通；</li><li>中间文件或最终报告能由人工直接核验；</li><li>高危敏感动作能停下来等人工弹窗批准。</li></ul><h3 id="适合的任务" tabindex="-1">适合的任务 <a class="header-anchor" href="#适合的任务" aria-label="Permalink to &quot;适合的任务&quot;">​</a></h3><p><strong>适合流程固定、高频重复且需跨工具调用的活。</strong></p><ul><li>情报巡检：定期访问固定官网出摘要表。</li><li>线索清洗：CRM 捞目标账户，结合公开信息起草外联信供审核。</li><li>财务对账：每周核对发票，标记缺票并催收。</li><li>缺陷复现：读 Issue 在预发布环境复现，提取日志与截图。</li><li>经营晨报：每天汇总库存指标，揪出异常点。</li></ul><h3 id="不适合的任务" tabindex="-1">不适合的任务 <a class="header-anchor" href="#不适合的任务" aria-label="Permalink to &quot;不适合的任务&quot;">​</a></h3><p><strong>别硬塞不匹配的活，容易白耗每周额度甚至失控。</strong></p><ul><li>即时问答：查报错用普通网页模型几秒搞定，不用云电脑。</li><li>本地写码：断点调试与 Git 冲突放本地 Codex CLI 或 Claude Code。</li><li>生活琐事：管日历缺乏企业级数据源，硬搬很别扭。</li><li>无增量轮询：每 5 分钟无条件刷新会空耗推理额度。</li><li>高危操作：群发邮件与删库必须留人工闸门。</li></ul><p>规划方法参考 <a href="https://jcng5q8n0f3z.feishu.cn/wiki/BnH9wLTmyiQZ03kJhsecOrffnAd" target="_blank" rel="noreferrer">《1.2 Grok Bot 和 Muse、Hermes、dots、Cue 怎么选》</a>。</p><h2 id="选型对照-grok-bot-与主流常驻-agent-横向对比" tabindex="-1">选型对照：Grok Bot 与主流常驻 Agent 横向对比 <a class="header-anchor" href="#选型对照-grok-bot-与主流常驻-agent-横向对比" aria-label="Permalink to &quot;选型对照：Grok Bot 与主流常驻 Agent 横向对比&quot;">​</a></h2><h3 id="整机与组装机形态" tabindex="-1">整机与组装机形态 <a class="header-anchor" href="#整机与组装机形态" aria-label="Permalink to &quot;整机与组装机形态&quot;">​</a></h3><p>选常驻 Agent 主要看图省心还是爱折腾。<strong>开箱即用的整机</strong>（Grok Bot、Muse）免去部署烦恼，但受平台额度限制；组装机（Hermes）接开源模型无额度约束，但环境报错得自己修。</p><h3 id="主流常驻-agent-特性与选型对照" tabindex="-1">主流常驻 Agent 特性与选型对照 <a class="header-anchor" href="#主流常驻-agent-特性与选型对照" aria-label="Permalink to &quot;主流常驻 Agent 特性与选型对照&quot;">​</a></h3><table tabindex="0"><thead><tr><th>产品</th><th>底座与门槛</th><th>特点与适用场景</th></tr></thead><tbody><tr><td>Grok Bot</td><td>共享 Linux 云电脑。2026-10-12 起执行 The X Subscription 统一方案（Premium $30/月、Super $100/月、Ultra $200/月），<strong>Plus 档不含 Bot</strong>；客户端 v0.70.2 支持独立邮箱与连接卡片</td><td>7×24 小时常驻，支持例程与技能，多 Bot 异步交接文件并调 X 平台检索。适合免运维、多岗位协同与巡检对账</td></tr><tr><td>OpenAI dots</td><td>个人常驻云电脑，ChatGPT Pro 档包含</td><td>基于 GPT-6 Astra（2026-09-30 发布），常驻后台连 4000 多个插件，主打日常伴随与轻量代办</td></tr><tr><td>Manus Cue</td><td>独立云电脑，处于早期体验阶段</td><td>2026-09-29 铁柱上手体验；原生配独立协同邮箱、电话与钱包，自主跑腿注册与采购，自主权极高且伴随操作风险</td></tr><tr><td>Meta Muse</td><td>Meta 托管云端代理，诺鸭船长评测偏家庭生态</td><td>深度绑定 Meta 社交网络与硬件，适合家庭日常与社交辅助</td></tr><tr><td>Hermes</td><td>本地或私有服务器，开源自建</td><td>自由更换开源模型，无商业额度限制。适合本地敏感数据流水线，<strong>需自己动手配环境与排错</strong></td></tr></tbody></table><p>详细推文对比参考 <a href="https://jcng5q8n0f3z.feishu.cn/wiki/RMRTwk3MqiUqEwk0TzTchA4LnDg" target="_blank" rel="noreferrer">《铁柱推文合集④：社区、生态与竞品对照》</a>。</p><h2 id="典型实战案例拆解" tabindex="-1">典型实战案例拆解 <a class="header-anchor" href="#典型实战案例拆解" aria-label="Permalink to &quot;典型实战案例拆解&quot;">​</a></h2><h3 id="金尘马的情报总监-个人调研岗位" tabindex="-1">金尘马的情报总监（个人调研岗位） <a class="header-anchor" href="#金尘马的情报总监-个人调研岗位" aria-label="Permalink to &quot;金尘马的情报总监（个人调研岗位）&quot;">​</a></h3><p>金尘马（@jinchenma_ai）在 Edit Profile 的 Description 写明长期岗位规则，定性为情报调研员。派单落实结果与来源、限制与格式及确认点五要素，检索 X 平台长文并区分视频帖，标明曝光数据，<strong>无一手数据严禁编造</strong>。</p><p>首次纠偏格式后，指令 Bot 把流程沉淀为 Skill「AI 教程情报搜集」。</p><p>换第二组输入测通后配置 Routine，定在每个工作日早上 8:10 自动执行汇报；新建「内容总监」评审选题，初稿存入 <code>/workspace/grokbot-demo/</code>。</p><p><strong>岗位说明沉淀长期规则，临时需求走消息</strong>，多 Bot 经 <code>/workspace</code> 落盘解耦。</p><p>细节见<a href="https://jcng5q8n0f3z.feishu.cn/wiki/MIKpwiUXpiE9mWkyG8ccFM6Znee" target="_blank" rel="noreferrer">《万字长文｜Grok Bot 从入门到精通｜金尘马》</a>。</p><h3 id="金尘马的电商运营团队-多角色分工流水线" tabindex="-1">金尘马的电商运营团队（多角色分工流水线） <a class="header-anchor" href="#金尘马的电商运营团队-多角色分工流水线" aria-label="Permalink to &quot;金尘马的电商运营团队（多角色分工流水线）&quot;">​</a></h3><p>团队由 4 个 Bot 协同。先建「店铺经营值班员」读商品表、库存表与订单表发晨报，<strong>卡死只读红线，严禁改价改库存，也不得发信或退款</strong>。</p><p>原值班员升级为「电商运营主管」，拆出内容增长专员、商品库存分析员与订单售后助理，数据存入 <code>/workspace/ecommerce-ops/日期/</code>。遇爆款仅剩 3 天库存，内容专员暂停推广，售后助理备好延期话术，主管汇总决策清单。</p><p>不要起手搭建庞大团队，<strong>涉及资金、库存与外部发信的操作全部锁定人工审批</strong>。</p><h3 id="铁柱的开源仓库管理员-bot-自动化运维巡检" tabindex="-1">铁柱的开源仓库管理员 Bot（自动化运维巡检） <a class="header-anchor" href="#铁柱的开源仓库管理员-bot-自动化运维巡检" aria-label="Permalink to &quot;铁柱的开源仓库管理员 Bot（自动化运维巡检）&quot;">​</a></h3><p>铁柱AGI（@cgnot996）建常驻 Bot 维护 awesome-grok-bot 知识库。系统定期巡检 X 平台推文、官方更新日志与技术社群，将新玩法、教程、官方文档和活动分类收录。</p><p>宣发前已自动收录相关资料，<strong>2026 年 8 月突破 130+ Star（作者自述，未核）</strong>，并获官方人员申请表单邀请。</p><h2 id="新手上路-从开通到第一个专职-bot" tabindex="-1">新手上路：从开通到第一个专职 Bot <a class="header-anchor" href="#新手上路-从开通到第一个专职-bot" aria-label="Permalink to &quot;新手上路：从开通到第一个专职 Bot&quot;">​</a></h2><p><img src="'+d+`" alt="新手上路：从开通到第一个专职 Bot" width="1600" height="1013" loading="lazy" decoding="async"></p><h3 id="确认订阅档位与安装客户端" tabindex="-1">确认订阅档位与安装客户端 <a class="header-anchor" href="#确认订阅档位与安装客户端" aria-label="Permalink to &quot;确认订阅档位与安装客户端&quot;">​</a></h3><p>按 2026 年 10 月 12 日起执行的 The X Subscription 统一方案选档：</p><ul><li><p><strong>Premium 档</strong>：$30/月（年付 $300），4x 额度池，个人日常起步选这档。</p></li><li><p><strong>Super 档</strong>：$100/月（年付 $1000），15x 额度池，适合重度研究与多例程。</p></li><li><p><strong>Ultra 档</strong>：$200/月（年付 $2000），50x 额度池，适合高频团队主力。</p></li><li><p><strong>$8/月（年付 $80）的 Plus 档不含 Bot 功能</strong>，千万别选错。已有 Cursor 付费个人版或团队版、SuperGrok 订阅或 Grok Business 席位也能直接用。</p><p>桌面端支持 macOS、Windows、Linux，移动端支持 iPhone，装好后登录账号。</p></li></ul><h3 id="创建-bot-并派发测试任务" tabindex="-1">创建 Bot 并派发测试任务 <a class="header-anchor" href="#创建-bot-并派发测试任务" aria-label="Permalink to &quot;创建 Bot 并派发测试任务&quot;">​</a></h3><ol><li>侧边栏点 New → Create new agent，起名「竞品情报员」。打开 Edit Profile，在 Description 填入标准六行工作合同。</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Own: 负责监控目标清单的每周功能更新与定价变动</span></span>
<span class="line"><span>Sources: Notion 中的关注名单、目标官网 Changelog 页面</span></span>
<span class="line"><span>Output: 不超过 8 条核心动态，附带日期与原始链接，存入 /workspace/scan.md</span></span>
<span class="line"><span>Approval: 严禁对外发布任何内容，严禁主动发送任何邮件</span></span>
<span class="line"><span>Failure: 若目标页面无法打开，在报告中明确标为数据缺失，严禁推测或编造内容</span></span>
<span class="line"><span>Never: 在源系统可访问时，严禁依赖自身记忆给出概括</span></span></code></pre></div><ol start="2"><li>在对话框下发测试指令，写明目标、来源、限制、格式及确认点五要素。</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>调研所附竞品清单中的前 3 个产品官网。</span></span>
<span class="line"><span>比对它们过去两周内的功能更新与价格调整。</span></span>
<span class="line"><span>跳过无任何变动的模块。</span></span>
<span class="line"><span>提取核心变动点，整理成 Markdown 表格，并直接保存到 /workspace/scan.md。</span></span>
<span class="line"><span>在对话框中仅回复处理状态与保存路径；不要对外发送任何通知，不要擅自更改系统设置。</span></span></code></pre></div><ol start="3"><li><strong>观察右侧云电脑窗口</strong>。Bot 会自动唤起云端浏览器提取页面，并把内容写入指定文件。</li></ol><h3 id="配置安全审批与定时例程" tabindex="-1">配置安全审批与定时例程 <a class="header-anchor" href="#配置安全审批与定时例程" aria-label="Permalink to &quot;配置安全审批与定时例程&quot;">​</a></h3><ol><li><p>进 Settings → General → Auto-review，<strong>高危操作必须全部开启 Ask first</strong>。</p><p>卡死发信（<code>send</code>）、发帖（<code>post</code>）、扣费（<code>buy</code>）、删文件（<code>delete</code>，含 <code>/workspace</code> 或本地文件）与改权限（<code>permissions</code>），触发后会弹卡片暂停，等你人工点批准。</p></li><li><p>抓取任务连续两次执行稳定后，在对话框发送沉淀指令。</p></li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>把刚才已经跑通的竞品页面抓取与格式整理流程保存为一个 Skill，名称叫「竞品动态巡检」。</span></span>
<span class="line"><span>写清调用条件、所需权限、抓取步骤、异常报错逻辑与产出文件格式。</span></span></code></pre></div><ol start="3"><li>换个竞品网址，输入 <code>/</code> 调这个 Skill 测试。确认无误后<strong>配置 Routine 定时</strong>，设在每周一早晨 9:00 自动运行，结果汇报发在当前对话，详细报告存入 <code>/workspace</code>。</li></ol><h2 id="容易踩的坑" tabindex="-1">容易踩的坑 <a class="header-anchor" href="#容易踩的坑" aria-label="Permalink to &quot;容易踩的坑&quot;">​</a></h2><h3 id="架构与安全" tabindex="-1">架构与安全 <a class="header-anchor" href="#架构与安全" aria-label="Permalink to &quot;架构与安全&quot;">​</a></h3><ul><li>看到社区 29 个 Bot 架构（Melvin Vivas 自述，未核）别跟风，同质化 Bot 易乱且费额度。<strong>一个岗位没跑顺前，不要建第二个</strong>。</li><li>所有 Bot 共享云电脑与文件系统，爬虫能读 <code>/workspace</code> 和 Cookie。<strong>安全控制只能靠 Ask first 人工审批闸门</strong>。</li><li>别在聊天框发账号密码。遇到登录界面，<strong>调出右侧屏幕点 Take over 按钮由人工登录</strong>。</li></ul><h3 id="资源与预期" tabindex="-1">资源与预期 <a class="header-anchor" href="#资源与预期" aria-label="Permalink to &quot;资源与预期&quot;">​</a></h3><ul><li>每月 $8 的 Plus 档没有 Bot 入口，<strong>必须认准每月 $30 起步的 Premium 档</strong>。</li><li>Routine 设 5 或 10 分钟轮询会掏空每周额度池。<strong>要拉长定时任务间隔，并加未更新即退出逻辑</strong>。</li><li>别轻信 Alex Finn 盈利或 0xkvro 降本神话（自述，未核），<strong>业务以实际跑通的指标为准</strong>。</li></ul><h2 id="做完怎么验收" tabindex="-1">做完怎么验收 <a class="header-anchor" href="#做完怎么验收" aria-label="Permalink to &quot;做完怎么验收&quot;">​</a></h2><ol><li>侧边栏点 Bot 进聊天，发消息展开 <strong>1920×1200 实时桌面</strong>；去 Usage &amp; Billing 确认方案是 Premium、Super 或 Ultra，进度条正常。</li><li>Edit Profile 的 Description 须写齐职责、数据源、产出物、审批红线与缺数兜底（<strong>六行硬约束</strong>）。发死链测它，<strong>必须如实报缺</strong>，不瞎编数据。</li><li>Settings → General → Auto-review 里，把 <code>send</code>、<code>post</code>、<code>buy</code>、<code>delete</code>、<code>permissions</code> 设为 Ask first。测发信或删文件，<strong>必须弹审批卡片等人工确认</strong>。</li><li>Routine 右键 Test run 跑通后合盖关软件。到点重开看提醒，进云电脑 <code>/workspace</code>，<strong>确认 Markdown 或 CSV 按最新时间戳更新</strong>。</li></ol><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><h3 id="相关章节" tabindex="-1">相关章节 <a class="header-anchor" href="#相关章节" aria-label="Permalink to &quot;相关章节&quot;">​</a></h3><ul><li><a href="/part1/05-computer">第 5 章 共享云电脑：文件、浏览器与接管</a></li><li><a href="/part1/06-memory">第 6 章 记忆：让 Bot 越用越懂你</a></li><li><a href="/part1/07-apps">第 7 章 连接应用：插件、邮箱与 Secrets</a></li><li><a href="/part1/11-safety">第 11 章 权限、安全与人闸</a></li><li><a href="/part1/grok-vs-grok-bot">Grok 和 Grok Bot 有什么区别</a></li><li><a href="/part1/02-plans">第 2 章 方案与订阅：先选对档位</a></li></ul><h3 id="官方页面与文档" tabindex="-1">官方页面与文档 <a class="header-anchor" href="#官方页面与文档" aria-label="Permalink to &quot;官方页面与文档&quot;">​</a></h3><ul><li><a href="https://cursor.com/cn/docs/grok-bot/get-started" target="_blank" rel="noreferrer">Grok Bot 快速入门指南</a></li><li><a href="https://cursor.com/cn/docs/grok-bot/work" target="_blank" rel="noreferrer">使用 Grok Bot：计算机、应用与任务</a></li><li><a href="https://cursor.com/cn/docs/grok-bot/use-cases" target="_blank" rel="noreferrer">Grok Bot 使用场景与典型角色</a></li><li><a href="https://cursor.com/cn/docs/grok-bot/teams" target="_blank" rel="noreferrer">面向团队版和企业版的 Grok Bot</a></li><li><a href="https://cursor.com/cn/help/grok-bot/plans" target="_blank" rel="noreferrer">Grok Bot 方案与计费说明</a></li><li><a href="https://cursor.com/cn/help/grok-bot/team-bots" target="_blank" rel="noreferrer">团队 Bot 使用规范</a></li><li><a href="https://cursor.com/cn/docs/grok-bot/security" target="_blank" rel="noreferrer">Grok Bot 安全架构与 Auto-review 规则</a></li></ul><h3 id="社区实战与横向对比" tabindex="-1">社区实战与横向对比 <a class="header-anchor" href="#社区实战与横向对比" aria-label="Permalink to &quot;社区实战与横向对比&quot;">​</a></h3><ul><li><a href="https://jcng5q8n0f3z.feishu.cn/wiki/I04Gw3wEaisftUkBikxcg43rnpc" target="_blank" rel="noreferrer">《1.1 Grok Bot 是什么：一页看懂》</a></li><li><a href="https://jcng5q8n0f3z.feishu.cn/wiki/BnH9wLTmyiQZ03kJhsecOrffnAd" target="_blank" rel="noreferrer">《1.2 Grok Bot 和 Muse、Hermes、dots、Cue 怎么选》</a></li><li><a href="https://jcng5q8n0f3z.feishu.cn/wiki/RMRTwk3MqiUqEwk0TzTchA4LnDg" target="_blank" rel="noreferrer">《铁柱推文合集④：社区、生态与竞品对照》</a></li><li><a href="https://jcng5q8n0f3z.feishu.cn/wiki/MIKpwiUXpiE9mWkyG8ccFM6Znee" target="_blank" rel="noreferrer">《万字长文｜Grok Bot 从入门到精通｜金尘马》</a></li></ul>`,80)])])}const B=a(h,[["render",p]]);export{m as __pageData,B as default};
